/* @jsx h */
import type { Register, Timer } from 'claude-code'
import { applyCommand, DEFAULTS, readConfig, type Config } from './cat/config.ts'
import { packCells } from './cat/pixels.ts'
import { BAND_ROWS, MIN_ROWS, renderScene } from './cat/scene.ts'

// The hooks module. While a turn runs it draws the band above the prompt as one Raster and
// paints the lot into it with $.ui.blit, which repaints a mounted Raster without a render
// pass, so the animation costs the transcript nothing. /maru changes the settings, kept in
// $.store.

const FRAME_MS = 40
const RASTER_KEY = 'maru'

let config: Config = DEFAULTS
/** The running turn, from the moment the cat set off. */
let turn: { startedAt: number } | undefined
/** The band this plugin last drew, which is what blit may repaint. */
let mount: { requestId: string; columns: number; rows: number } | undefined
let frames: Timer | undefined
/** The word the spinner reads, as the last frame left it. */
let word: string | undefined

const log = ($: { ui: { log: (text: string) => void } }, what: string) => (err: unknown) =>
  $.ui.log(`claude-maru-run: ${what}: ${err}`)

export const register: Register = on => {
  /** The band's size for a render, or nothing when it has no room for the cat. */
  const bandSize = (props: { bodyColumns: number; maxRows: number }): { columns: number; rows: number } | undefined => {
    const columns = Math.min(512, Math.floor(props.bodyColumns))
    const rows = Math.min(BAND_ROWS, Math.floor(props.maxRows))
    return columns >= 16 && rows >= MIN_ROWS ? { columns, rows } : undefined
  }

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    const saved = await $.store.get('config').catch(log($, 'store read failed'))
    config = readConfig(saved)
    await $.command.register({
      name: 'maru',
      description: 'An orange-and-white cat playing in a vacant lot above the prompt while Claude works: on, off, slow, normal, fast, delay, spinner (claude-maru-run)',
      argumentHint: '[on | off | slow | normal | fast | delay <s> | spinner on|off | help]',
      immediate: true,
    }).catch(log($, '/maru not registered'))
    return r
  })

  on('command.run', { command: 'maru' }, async ($, e) => {
    const applied = applyCommand(config, e.args)
    if (applied.config !== config) {
      config = applied.config
      await $.store.set('config', config).catch(log($, 'store write failed'))
      $.ui.invalidate('ui.render')
    }
    return { text: applied.text }
  })

  on('turn.start', async ($, e, next) => {
    turn = { startedAt: await $.clock.now() }
    word = undefined
    frames?.cancel()
    // every frame after this one is a blit into the mounted Raster: no redraw, no transcript
    frames = $.clock.every(FRAME_MS, () => {
      const at = turn
      const band = mount
      if (!at || !band || !config.enabled) return
      $.clock.now().then(now => {
        const elapsedMs = now - at.startedAt - config.delay * 1000
        if (elapsedMs < 0) return
        const { requestId, columns, rows } = band
        const scene = renderScene({ columns, rows, elapsedMs, speed: config.speed })
        $.ui.blit({ requestId, key: RASTER_KEY, columns, rows, cells: packCells(scene.cells) })
          .catch(log($, 'blit failed'))
        if (scene.word !== word) {
          word = scene.word
          if (config.spinner) $.ui.invalidate('ui.render')
        }
      }).catch(log($, 'frame failed'))
    })
    // the band is drawn from the delay on: wake the render hook when it has passed
    if (config.delay > 0) $.clock.after(config.delay * 1000, () => $.ui.invalidate('ui.render'))
    $.ui.invalidate('ui.render')
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    frames?.cancel()
    frames = undefined
    turn = undefined
    mount = undefined
    word = undefined
    $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // a Raster is the terminal's alone, and a survey keeps the band
    if (e.surface !== 'terminal' || !config.enabled || !e.props.isWorking || e.props.hasSurvey) {
      mount = undefined
      return next(e)
    }
    const band = bandSize(e.props)
    if (!band) {
      mount = undefined
      return next(e)
    }
    const now = await $.clock.now()
    // a turn this module saw start, or one already running when it loaded
    const at = turn ?? (turn = { startedAt: now })
    const elapsedMs = now - at.startedAt - config.delay * 1000
    if (elapsedMs < 0) {
      mount = undefined
      return next(e)
    }
    const scene = renderScene({ columns: band.columns, rows: band.rows, elapsedMs, speed: config.speed })
    word = scene.word
    mount = { requestId: e.requestId, ...band }
    const { Box, Raster } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        <Raster key={RASTER_KEY} columns={band.columns} rows={band.rows} cells={packCells(scene.cells)} />
        {await next(e)}
      </Box>
    )
  })

  // the spinner's word becomes whatever the cat is up to: `✻ Pouncing… (12s)`
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    if (!config.enabled || !config.spinner || !turn || !word) return next(e)
    return next({ ...e, props: { ...e.props, word } })
  })
}

