// The plugin's settings and the /maru command that changes them. Pure: `claude plugin test`
// covers it.

import { isSpeed, rateOf, SPEEDS, type Speed } from './story.ts'

export type Config = {
  enabled: boolean
  speed: Speed
  /** Seconds Claude works before the cat appears; 0 shows it at once. */
  delay: number
  /** Whether the spinner's word says what the cat is doing. */
  spinner: boolean
}

export const DEFAULTS: Config = { enabled: true, speed: 'normal', delay: 0, spinner: true }

/** A config from what the store held, field by field, defaults for the rest. */
export function readConfig(saved: unknown): Config {
  const s = (typeof saved === 'object' && saved !== null ? saved : {}) as Record<string, unknown>
  return {
    enabled: typeof s.enabled === 'boolean' ? s.enabled : DEFAULTS.enabled,
    speed: isSpeed(s.speed) ? s.speed : DEFAULTS.speed,
    delay: typeof s.delay === 'number' && s.delay >= 0 && Number.isFinite(s.delay) ? s.delay : DEFAULTS.delay,
    spinner: typeof s.spinner === 'boolean' ? s.spinner : DEFAULTS.spinner,
  }
}

export function statusLine(c: Config): string {
  return `maru: ${c.enabled ? 'on' : 'off'} · ${c.speed} (\u00d7${rateOf(c.speed)}) · delay ${c.delay}s · spinner ${c.spinner ? 'on' : 'off'}`
}

export const HELP = [
  '/maru                  status',
  '/maru on | off         show or hide the cat while Claude works',
  `/maru ${SPEEDS.join(' | ')}  how fast the chase runs`,
  '/maru delay <s>        seconds Claude works before the cat appears (0 = at once)',
  '/maru spinner on|off   let the spinner say what the cat is doing',
].join('\n')

/** Applies one `/maru` invocation; returns the new config and the transcript line. */
export function applyCommand(config: Config, args: string): { config: Config; text: string } {
  const words = args.trim().toLowerCase().split(/\s+/).filter(Boolean)
  const [head, arg] = words
  if (!head || head === 'status') return { config, text: statusLine(config) }
  if (head === 'help') return { config, text: HELP }
  if (head === 'on' || head === 'off') {
    const next: Config = { ...config, enabled: head === 'on' }
    return { config: next, text: statusLine(next) }
  }
  if (isSpeed(head)) {
    const next: Config = { ...config, speed: head }
    return { config: next, text: statusLine(next) }
  }
  if (head === 'speed') {
    if (isSpeed(arg)) {
      const next: Config = { ...config, speed: arg }
      return { config: next, text: statusLine(next) }
    }
    return { config, text: `maru: speed is one of ${SPEEDS.join(', ')}` }
  }
  if (head === 'delay') {
    const delay = Number(arg)
    if (arg !== undefined && Number.isFinite(delay) && delay >= 0) {
      const next: Config = { ...config, delay }
      return { config: next, text: statusLine(next) }
    }
    return { config, text: 'maru: delay takes a number of seconds, 0 or more' }
  }
  if (head === 'spinner') {
    if (arg === 'on' || arg === 'off') {
      const next: Config = { ...config, spinner: arg === 'on' }
      return { config: next, text: statusLine(next) }
    }
    return { config, text: 'maru: spinner on or off' }
  }
  return { config, text: `maru: no setting called "${head}"\n${HELP}` }
}

