// The band as pixels and then as Raster cells. Two pixels share one terminal cell: the cell
// draws `▀`, its foreground the upper pixel and its background the lower one, so the picture
// has twice the rows the band does and a pixel is about square. Pure: `claude plugin test`
// covers it.

import { DEFAULT_COLOR, TRANSPARENT } from './palette.ts'

/** A picture, `width` by `height` pixels, each a colour or TRANSPARENT. */
export type Pixels = {
  readonly width: number
  readonly height: number
  readonly data: Int32Array
}

export const createPixels = (width: number, height: number): Pixels => ({
  width,
  height,
  data: new Int32Array(width * height).fill(TRANSPARENT),
})

export function setPixel(px: Pixels, x: number, y: number, color: number): void {
  if (x < 0 || y < 0 || x >= px.width || y >= px.height) return
  px.data[y * px.width + x] = color
}

export function getPixel(px: Pixels, x: number, y: number): number {
  if (x < 0 || y < 0 || x >= px.width || y >= px.height) return TRANSPARENT
  return px.data[y * px.width + x] ?? TRANSPARENT
}

/** One Raster cell: a printable width-1 character and its two colours. */
export type Cell = { ch: string; fg: number; bg: number }

export const blankCell = (): Cell => ({ ch: ' ', fg: DEFAULT_COLOR, bg: DEFAULT_COLOR })

const UPPER = '▀' // ▀
const LOWER = '▄' // ▄

/**
 * The cell two stacked pixels make: `▀` when both are drawn, the single half block when one
 * is, a space when neither. `height` must be even; row `r` of cells takes pixel rows `2r`
 * and `2r+1`.
 */
export function cellsFromPixels(px: Pixels): Cell[] {
  const rows = px.height >> 1
  const cells: Cell[] = []
  for (let r = 0; r < rows; r++) {
    for (let x = 0; x < px.width; x++) {
      const top = getPixel(px, x, r * 2)
      const bottom = getPixel(px, x, r * 2 + 1)
      if (top === TRANSPARENT && bottom === TRANSPARENT) cells.push(blankCell())
      else if (bottom === TRANSPARENT) cells.push({ ch: UPPER, fg: top, bg: DEFAULT_COLOR })
      else if (top === TRANSPARENT) cells.push({ ch: LOWER, fg: bottom, bg: DEFAULT_COLOR })
      else cells.push({ ch: UPPER, fg: top, bg: bottom })
    }
  }
  return cells
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** Standard padded base64 of `bytes`; the environment has no Buffer and no atob. */
export function toBase64(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i] ?? 0
    const b = bytes[i + 1] ?? 0
    const c = bytes[i + 2] ?? 0
    const left = bytes.length - i
    out += B64[a >> 2]
    out += B64[((a & 3) << 4) | (b >> 4)]
    out += left > 1 ? B64[((b & 15) << 2) | (c >> 6)] : '='
    out += left > 2 ? B64[c & 63] : '='
  }
  return out
}

/**
 * The `cells` a Raster takes: little-endian u32 triplets `[codePoint, foreground, background]`,
 * row-major, in base64. A character outside the BMP, or wider than one cell, is refused by the
 * surface, so only the characters this plugin draws reach it.
 */
export function packCells(cells: readonly Cell[]): string {
  const words = new Uint32Array(cells.length * 3)
  cells.forEach((cell, i) => {
    words[i * 3] = cell.ch.codePointAt(0) ?? 0x20
    words[i * 3 + 1] = cell.fg
    words[i * 3 + 2] = cell.bg
  })
  return toBase64(new Uint8Array(words.buffer))
}

