// The band, frame by frame: the lot the chase runs through, the butterfly, and the cat after
// it. The eye follows the cat part of the way, so the trees and the grass slide past it. The
// whole band is one Raster, so a frame is one `$.ui.blit` and nothing else redraws. Pure:
// `claude plugin test` covers it.

import { drawSprite } from './art.ts'
import { CAT_WIDTH, GATHER, LEAP, REACH } from './frames.ts'
import { cellsFromPixels, createPixels, type Cell, type Pixels } from './pixels.ts'
import { BUTTERFLY, drawGrass, drawGround, drawTrees } from './props.ts'
import { drawCat as drawCurledCat } from './sprite.ts'
import { chaseAt, stageFor, wordFor, type Chase, type Speed } from './story.ts'

/** Rows the band takes: all of them are picture. */
export const BAND_ROWS = 7
/** The fewest rows worth drawing the chase in: below this the cat loses its ears. */
export const MIN_ROWS = 4
/** The curled cat's radius while it tumbles. */
const TUMBLE_RADIUS = 2.6
/** How much of the cat's run the eye follows; the lot slides the rest of the way past it. */
const CAMERA_FOLLOW = 0.3

function drawCat(px: Pixels, chase: Chase, groundY: number): void {
  if (chase.act === 'tumble') {
    drawCurledCat(px, chase.x + CAT_WIDTH / 2, groundY - 1 - TUMBLE_RADIUS, TUMBLE_RADIUS, chase.angle)
    return
  }
  const sprite = chase.act === 'reach' ? REACH : chase.airborne ? LEAP : GATHER
  drawSprite(px, sprite, chase.x, chase.y, { flip: chase.facing === -1 })
}

export type SceneInput = {
  /** The band's width in cells (`e.props.bodyColumns`). */
  columns: number
  /** The band's height in cells; a short band keeps the ground and loses the sky. */
  rows: number
  /** How long the turn has been running. */
  elapsedMs: number
  speed: Speed
}

export type Scene = {
  /** Every cell of the band, row-major, `columns * rows` of them. */
  cells: Cell[]
  /** The word for the spinner this frame. */
  word: string
}

/** The band as it looks `elapsedMs` into the turn. */
export function renderScene(input: SceneInput): Scene {
  const columns = Math.max(1, Math.min(512, Math.floor(input.columns)))
  const rows = Math.max(1, Math.min(256, Math.floor(input.rows)))
  const px = createPixels(columns, rows * 2)
  const stage = stageFor(px.width, px.height)
  const chase = chaseAt(input.elapsedMs, stage, input.speed)

  const camera = chase.x * CAMERA_FOLLOW

  drawTrees(px, stage.groundY, camera)
  drawGround(px, stage.groundY, camera)
  drawGrass(px, stage.groundY, camera)
  drawCat(px, chase, stage.groundY)
  // the butterfly stays in front: the cat never gets between it and the eye
  drawSprite(px, BUTTERFLY[chase.butterfly.frame] ?? BUTTERFLY[0]!, chase.butterfly.x, chase.butterfly.y)

  return { cells: cellsFromPixels(px), word: wordFor(chase.act) }
}

