// The chase: where the butterfly is and where the cat is, at any moment. Both are pure
// functions of the time, so any frame can be drawn from the clock alone and every part of it
// can be tested on its own.
//
// The butterfly wanders the band on two sines that never line up, and swoops low every few
// seconds. The cat runs the butterfly's own path a moment behind it — which is what chasing
// looks like — bounding as it goes, and when the butterfly comes down within reach it leaps,
// misses, and tumbles.

import { CAT_HEIGHT, CAT_WIDTH } from './frames.ts'
import { BUTTERFLY_HEIGHT, BUTTERFLY_WIDTH } from './props.ts'

export type Speed = 'slow' | 'normal' | 'fast'

export const SPEEDS: readonly Speed[] = ['slow', 'normal', 'fast']

export const isSpeed = (value: unknown): value is Speed =>
  typeof value === 'string' && (SPEEDS as readonly string[]).includes(value)

/** How fast the whole chase runs; everything else is timed off it. */
const RATE: Record<Speed, number> = { slow: 0.65, normal: 1, fast: 1.6 }

export const rateOf = (speed: Speed): number => RATE[speed]

/**
 * The pace of the whole thing at `normal`. Every part of the chase is a function of `t`, so
 * this stretches the lot evenly — the same chase, at a pace the eye can follow rather than one
 * that reads as fast forward.
 */
const TEMPO = 0.62

/** How often the butterfly comes down within reach, in seconds of chase time. */
const SWOOP_PERIOD = 5
/** One bound of the cat, and how high the fastest bound takes it. */
const HOP_PERIOD = 0.34
const HOP_LOW = 0.7
const HOP_HIGH = 2.4
/** How much of its speed a bound is worth: a slower chase would bound lower without it. */
const HOP_FROM_SPEED = 0.1
/** Shapes the bound: above one, the arc is sharper and the landing is a real beat. */
const HOP_SHAPE = 1.7
/** How high the leap at the butterfly goes: just enough for its paws to reach. */
const LEAP_HEIGHT = 3
/** How far behind the butterfly the cat runs, and how far behind while it closes in. */
const LAG_FAR = 0.6
const LAG_NEAR = 0.12
/** How far the cat carries past a turn before it can pull round: what makes it a chase. */
const OVERSHOOT = 0.22
/** The most it ever carries, in pixels, so a wide band does not fling it into the edge. */
const OVERSHOOT_MAX = 6
/** Where in a swoop the cat leaps, and where it lands in a heap. */
const REACH_FROM = 0.17
const REACH_TO = 0.28
const TUMBLE_TO = 0.36

/** What the cat is doing; each one draws a different pose. */
export type Act = 'bound' | 'reach' | 'tumble'

export type Stage = {
  width: number
  height: number
  /** The row the ground is drawn on; the cat stands on top of it. */
  groundY: number
}

export const stageFor = (width: number, height: number): Stage => ({
  width,
  height,
  groundY: height - 1,
})

const clamp = (value: number, low: number, high: number): number =>
  Math.max(low, Math.min(high, value))

/** Smooth 0 to 1 across `[from, to]`, flat outside it. */
function ramp(value: number, from: number, to: number): number {
  const t = clamp((value - from) / (to - from), 0, 1)
  return t * t * (3 - 2 * t)
}

/** How far into the current swoop, 0 to 1: it comes down at a quarter and climbs away after. */
export const swoopPhase = (t: number): number => ((t / SWOOP_PERIOD) % 1 + 1) % 1

/** The butterfly at `t` seconds: its top left corner, and how low the swoop has brought it. */
export function butterflyAt(t: number, stage: Stage): { x: number; y: number; swoop: number; frame: number } {
  const span = Math.max(1, (stage.width - BUTTERFLY_WIDTH) / 2 - 2)
  const drift = 0.55 * Math.sin(t * 0.82) + 0.3 * Math.sin(t * 1.73 + 0.8) + 0.15 * Math.sin(t * 3.4 + 2.1)
  const swoop = Math.max(0, Math.sin(swoopPhase(t) * Math.PI * 2)) ** 3
  // low enough for the cat to have a go at it, never so low it lands
  const low = stage.groundY - CAT_HEIGHT - BUTTERFLY_HEIGHT + 1
  const y = low * swoop + Math.sin(t * 5.1) * 0.7
  return {
    x: clamp(stage.width / 2 + span * drift, 0, Math.max(0, stage.width - BUTTERFLY_WIDTH)),
    y: clamp(y, 0, Math.max(0, stage.groundY - BUTTERFLY_HEIGHT)),
    swoop,
    frame: Math.floor(t * 9) % 2,
  }
}

/** Where the cat would be at `t`: on the butterfly's path, a moment behind it. */
function catX(t: number, stage: Stage): number {
  const phase = swoopPhase(t)
  // it closes the gap as the butterfly comes down, and drops back once it has gone
  const near = ramp(phase, REACH_FROM - 0.09, REACH_FROM) * (1 - ramp(phase, TUMBLE_TO, TUMBLE_TO + 0.1))
  const lag = LAG_FAR + (LAG_NEAR - LAG_FAR) * near
  const ahead = butterflyAt(t - lag, stage).x
  // the cat carries its own speed past every turn the butterfly makes, then has to come back
  const carry = clamp((ahead - butterflyAt(t - lag - 0.1, stage).x) / 0.1 * OVERSHOOT, -OVERSHOOT_MAX, OVERSHOOT_MAX)
  return clamp(ahead + carry - (CAT_WIDTH - BUTTERFLY_WIDTH) / 2, 0, Math.max(0, stage.width - CAT_WIDTH))
}

export type Chase = {
  act: Act
  /** The top left of the cat's sprite. */
  x: number
  y: number
  facing: 1 | -1
  /** True while the cat is off the ground: the stretched frame is drawn then. */
  airborne: boolean
  /** How far the cat has rolled, for the tumble. */
  angle: number
  butterfly: { x: number; y: number; frame: number }
  /** How many swoops have gone by. */
  lap: number
}

/** The whole picture at `elapsedMs` into the turn. */
export function chaseAt(elapsedMs: number, stage: Stage, speed: Speed): Chase {
  const t = Math.max(0, elapsedMs) / 1000 * rateOf(speed) * TEMPO
  const phase = swoopPhase(t)
  const butterfly = butterflyAt(t, stage)
  const x = catX(t, stage)
  const was = catX(t - 0.14, stage)
  const speedX = (x - was) / 0.14
  // going somewhere, it faces the way it is going; slowing, or swiping, it faces the butterfly
  const towards: 1 | -1 = butterfly.x + BUTTERFLY_WIDTH / 2 >= x + CAT_WIDTH / 2 ? 1 : -1
  const facing: 1 | -1 = Math.abs(speedX) < 0.6 ? towards : speedX > 0 ? 1 : -1
  const standY = stage.groundY - CAT_HEIGHT

  if (phase >= REACH_FROM && phase < REACH_TO) {
    // the leap: one arc that takes the cat up under the butterfly
    const through = (phase - REACH_FROM) / (REACH_TO - REACH_FROM)
    return {
      act: 'reach',
      x,
      y: standY - Math.sin(Math.PI * through) * LEAP_HEIGHT,
      facing: towards,
      airborne: true,
      angle: 0,
      butterfly,
      lap: Math.floor(t / SWOOP_PERIOD),
    }
  }

  if (phase >= REACH_TO && phase < TUMBLE_TO) {
    const through = (phase - REACH_TO) / (TUMBLE_TO - REACH_TO)
    return {
      act: 'tumble',
      x,
      y: standY,
      facing,
      airborne: false,
      angle: -facing * through * 7,
      butterfly,
      lap: Math.floor(t / SWOOP_PERIOD),
    }
  }

  // bounding after it: the faster it runs, the higher it bounds
  const height = HOP_LOW + Math.min(HOP_HIGH - HOP_LOW, Math.abs(speedX) * HOP_FROM_SPEED)
  const hop = height * Math.abs(Math.sin((Math.PI * t) / HOP_PERIOD)) ** HOP_SHAPE
  return {
    act: 'bound',
    x,
    y: standY - hop,
    facing,
    airborne: hop > height * 0.45,
    angle: 0,
    butterfly,
    lap: Math.floor(t / SWOOP_PERIOD),
  }
}

/** The word the spinner reads while the cat is at it. */
const WORDS: Record<Act, string> = {
  bound: 'Chasing',
  reach: 'Pouncing',
  tumble: 'Tumbling',
}

export const wordFor = (act: Act): string => WORDS[act]

