// Sprites as text: a picture is rows of letters from the palette's INK, `.` for nothing, and
// the drawing puts one letter in one pixel. Frames are written facing right and mirrored for
// the walk back. Pure: `claude plugin test` covers it.

import { INK, TRANSPARENT } from './palette.ts'
import { setPixel, type Pixels } from './pixels.ts'

/** A picture, one string a row; every row of one sprite is the same width. */
export type Sprite = readonly string[]

export const spriteWidth = (sprite: Sprite): number => Math.max(0, ...sprite.map(row => row.length))

/** The colour a letter paints, or TRANSPARENT for `.` and anything unwritten. */
export const inkOf = (letter: string): number => INK[letter] ?? TRANSPARENT

export type DrawOptions = {
  /** Draws the sprite mirrored, for a cat walking the other way. */
  flip?: boolean
}

/** Draws `sprite` with its top left corner at (`x`, `y`), one letter to a pixel. */
export function drawSprite(px: Pixels, sprite: Sprite, x: number, y: number, options: DrawOptions = {}): void {
  const width = spriteWidth(sprite)
  sprite.forEach((row, dy) => {
    for (let dx = 0; dx < row.length; dx++) {
      const color = inkOf(row[dx] ?? '.')
      if (color === TRANSPARENT) continue
      setPixel(px, Math.round(x) + (options.flip ? width - 1 - dx : dx), Math.round(y) + dy, color)
    }
  })
}

