// What the cat chases, and the lot it chases through: the trees behind it, the grass underfoot
// and the ground itself. The lot is a world wider than the band — everything in it is placed by
// its world position and drawn where the eye currently is, so it slides past as the cat runs.
// How far a layer slides is how near it is: the trees barely move, the grass keeps up.

import { drawSprite, spriteWidth, type Sprite } from './art.ts'
import type { Pixels } from './pixels.ts'

/** The butterfly, wings up and wings out; it never stops flapping. */
export const BUTTERFLY: readonly Sprite[] = [
  [
    'b.b',
    '.B.',
    'b.b',
  ],
  [
    '...',
    'bBb',
    '.b.',
  ],
]

export const BUTTERFLY_WIDTH = 3
export const BUTTERFLY_HEIGHT = 3

/** How far each layer slides for one pixel the eye moves: 1 is underfoot, 0 is the horizon. */
const TREE_PARALLAX = 0.3
const GROUND_PARALLAX = 1

/** A tree: the crown, and which of its columns the trunk comes down from. */
type Tree = { crown: Sprite; trunkAt: number }

/**
 * The crowns along the back of the lot: four of them, none the same width or shade. The flat
 * dark one reads as furthest off. Each one gets its own trunk length, so two of the same crown
 * are still two different trees.
 */
const TREES: readonly Tree[] = [
  {
    crown: [
      '...GGG...',
      '..GgggG..',
      '.GgggggG.',
      'GggggggGG',
      '.GgggggG.',
      '..GgggG..',
    ],
    trunkAt: 4,
  },
  {
    crown: [
      '..GGG..',
      '.GgggG.',
      'GgggggG',
      '.GgggG.',
    ],
    trunkAt: 3,
  },
  {
    crown: [
      '.GGG.',
      'GGGGG',
      'GGGGG',
      '.GGG.',
    ],
    trunkAt: 2,
  },
  {
    crown: [
      '..GGG...',
      '.GgggG..',
      'GgggggG.',
      '.GggggGG',
      '..GgggG.',
    ],
    trunkAt: 3,
  },
]

/** How far apart the trees stand on average, and how far off that beat each one may stand. */
const TREE_SPACING = 24
const TREE_WANDER = 11
/** How tall a tree stands altogether: every one of them carries its crown clear of the cat. */
const TREE_LOW = 10
const TREE_HIGH = 13

/** Tufts of grass, from bare ground through a blade or two to a clump. */
const TUFTS: readonly Sprite[] = [
  ['.'],
  ['.'],
  ['s'],
  ['g'],
  ['s', 'g'],
  ['g', 'G'],
  ['.s.', 'GsG'],
  ['s.s', '.g.'],
]

/** How thick the grass grows, before each tuft is nudged off the beat. */
const TUFT_SPACING = 5

/** The widest of a layer's sprites: how far off the left edge one can start and still show. */
const widest = (sprites: readonly Sprite[]): number => Math.max(...sprites.map(spriteWidth))

/**
 * A settled scatter, 0 to 1: the same place in the world always grows the same thing, but the
 * lot never falls into a pattern the eye can pick up as it slides by.
 */
function scatter(i: number): number {
  let h = Math.imul(i ^ 0x9e3779b9, 0x85ebca6b)
  h ^= h >>> 13
  h = Math.imul(h, 0xc2b2ae35)
  return (h >>> 0) / 0x1_0000_0000
}

/** One of `choices`, settled by the scatter at `i`. */
const pick = <T>(choices: readonly T[], i: number): T =>
  choices[Math.min(choices.length - 1, Math.floor(scatter(i) * choices.length))]!

/**
 * Walks the world positions of one layer that fall on the band, `i` counting from the
 * leftmost. `shift` is how far the world has slid under the eye at this layer's depth.
 */
function alongTheBand(
  px: Pixels,
  spacing: number,
  shift: number,
  widest: number,
  place: (i: number, x: number) => void,
): void {
  const first = Math.floor((shift - widest) / spacing)
  const last = Math.ceil((shift + px.width) / spacing)
  for (let i = first; i <= last; i++) place(i, i * spacing - shift)
}

/** Draws one tree with its foot on the ground, `height` pixels from its roots to its crown. */
function drawTree(px: Pixels, tree: Tree, x: number, groundY: number, height: number): void {
  const trunk = Math.max(2, height - tree.crown.length)
  drawSprite(px, tree.crown, x, groundY - height)
  const foot = groundY - 1
  for (let y = foot - trunk + 1; y <= foot; y++) {
    // it flares out where it goes into the ground
    drawSprite(px, [y === foot ? 'TTT' : '.T.'], x + tree.trunkAt - 1, y)
  }
}

/** Draws the trees along the back of the lot, as the eye at `camera` sees them. */
export function drawTrees(px: Pixels, groundY: number, camera: number): void {
  const margin = widest(TREES.map(tree => tree.crown)) + TREE_WANDER
  alongTheBand(px, TREE_SPACING, camera * TREE_PARALLAX, margin, (i, x) => {
    // well off the beat, and no two the same height: a stand of trees, not a row of fence posts
    const wander = Math.floor(scatter(i + 101) * (TREE_WANDER * 2 + 1)) - TREE_WANDER
    const height = TREE_LOW + Math.floor(scatter(i + 41) * (TREE_HIGH - TREE_LOW + 1))
    // the band only ever shows a handful of trees: this stretch of the scatter gives that
    // handful all four crowns, with no two neighbours alike
    drawTree(px, pick(TREES, i + 5), x + wander, groundY, height)
  })
}

/** Draws the grass the cat runs through, the near layer that keeps up with it. */
export function drawGrass(px: Pixels, groundY: number, camera: number): void {
  alongTheBand(px, TUFT_SPACING, camera * GROUND_PARALLAX, widest(TUFTS), (i, x) => {
    const tuft = pick(TUFTS, i)
    drawSprite(px, tuft, x + Math.floor(scatter(i + 7) * 3), groundY - tuft.length)
  })
}

/** Draws the ground the chase runs over, with grit in it that slides by as the cat runs. */
export function drawGround(px: Pixels, groundY: number, camera: number): void {
  const shift = Math.round(camera * GROUND_PARALLAX)
  for (let x = 0; x < px.width; x++) {
    drawSprite(px, [scatter(x + shift) < 0.14 ? 'D' : 'd'], x, groundY)
  }
}

