// The cat itself: a curled orange-and-white cat drawn into the pixel picture at any angle, so
// rolling is one sprite turned a little more each frame rather than a strip of frames.
//
// Every feature is stated in the cat's own frame, a disc of radius 1 with the head up: the
// drawing walks the pixels the cat can cover, turns each one back into that frame, and asks
// which feature it lands on. Pure: `claude plugin test` covers it.

import { EYE, FUR, FUR_STRIPE, PINK, TRANSPARENT, WHITE } from './palette.ts'
import { setPixel, type Pixels } from './pixels.ts'

/** How far past the body the ears and the tail reach, as a factor of the radius. */
const REACH = 1.38

type Point = readonly [number, number]

const dist2 = (x: number, y: number, p: Point): number => (x - p[0]) ** 2 + (y - p[1]) ** 2

/** A point inside the triangle an ear makes, narrowing from `base` to `tip`. */
function inEar(x: number, y: number, base: Point, tip: Point, halfWidth: number): boolean {
  const ax = tip[0] - base[0]
  const ay = tip[1] - base[1]
  const len2 = ax * ax + ay * ay
  const t = ((x - base[0]) * ax + (y - base[1]) * ay) / len2
  if (t < 0 || t > 1) return false
  const px = base[0] + ax * t
  const py = base[1] + ay * t
  return Math.hypot(x - px, y - py) <= halfWidth * (1 - t * 0.85)
}

const EAR_L = { base: [-0.5, 0.68] as Point, tip: [-0.72, 1.28] as Point }
const EAR_R = { base: [0.5, 0.68] as Point, tip: [0.72, 1.28] as Point }
const EYE_L: Point = [-0.36, 0.46]
const EYE_R: Point = [0.36, 0.46]
const MUZZLE: Point = [0, 0.16]
const NOSE: Point = [0, 0.3]
const BELLY: Point = [0, -0.5]
const PAW_L: Point = [-0.44, -0.86]
const PAW_R: Point = [0.44, -0.86]

/**
 * The colour of the cat at one point of its own frame, or TRANSPARENT where the cat is not.
 * `x` is right and `y` is up, both in radii, the head at `y = 1`.
 */
export function furAt(x: number, y: number): number {
  const r2 = x * x + y * y
  if (r2 > 1) {
    // outside the body: an ear, or the tail curled round the right of the ball
    if (inEar(x, y, EAR_L.base, EAR_L.tip, 0.3) || inEar(x, y, EAR_R.base, EAR_R.tip, 0.3)) {
      const inner = inEar(x, y, EAR_L.base, EAR_L.tip, 0.15) || inEar(x, y, EAR_R.base, EAR_R.tip, 0.15)
      return inner && y < 1.12 ? PINK : FUR
    }
    const r = Math.sqrt(r2)
    if (Math.abs(r - 1.19) <= 0.23) {
      const a = Math.atan2(y, x)
      if (a >= -2.25 && a <= 0.45) return a <= -1.85 ? WHITE : FUR
    }
    return TRANSPARENT
  }
  // the face
  if (dist2(x, y, EYE_L) <= 0.014 || dist2(x, y, EYE_R) <= 0.014) return EYE
  if (dist2(x, y, NOSE) <= 0.006) return PINK
  if (dist2(x, y, MUZZLE) <= 0.075) return WHITE
  // the white front: belly, chest and the paws tucked into it
  if (dist2(x, y, PAW_L) <= 0.01 || dist2(x, y, PAW_R) <= 0.01) return PINK
  if (dist2(x, y, BELLY) <= 0.29) return WHITE
  // the tabby's bands, spokes around the curled body: they are what the eye sees turning
  if (r2 > 0.5 && Math.sin(Math.atan2(y, x) * 7) > 0.35) return FUR_STRIPE
  return FUR
}

/**
 * Draws the cat centred on (`cx`, `cy`) with body radius `radius`, turned `angle` radians
 * clockwise. Pixels are square: one pixel across is one column, one pixel down is half a row.
 */
export function drawCat(px: Pixels, cx: number, cy: number, radius: number, angle: number): void {
  const cos = Math.cos(angle)
  const sin = Math.sin(angle)
  const reach = Math.ceil(radius * REACH) + 1
  for (let y = Math.floor(cy - reach); y <= Math.ceil(cy + reach); y++) {
    for (let x = Math.floor(cx - reach); x <= Math.ceil(cx + reach); x++) {
      // the pixel in screen terms, y up, then turned back into the cat's own frame
      const sx = (x - cx) / radius
      const sy = (cy - y) / radius
      const color = furAt(sx * cos - sy * sin, sx * sin + sy * cos)
      if (color !== TRANSPARENT) setPixel(px, x, y, color)
    }
  }
}

